 	if (iter != entries.end()) {
 		hAlloc->FreeHandle(handle);
 		iter->second.Close();
 		entries.erase(iter);
 	} else {
 		//This shouldn't happen...
 		ERROR_LOG(HLE,"VirtualDiscFileSystem: Cannot close file that hasn't been opened: %08x", handle);
 	}
