		if (Microphone::isMicStarted())
			Microphone::stopMic();
	} else if (micState == 1) {
		if (Microphone::isMicStarted()) {
			Microphone::stopMic();
			Microphone::startMic(new std::vector<u32>({ curSampleRate, curChannels }));
		} else {
			Microphone::startMic(new std::vector<u32>({ curSampleRate, curChannels }));
